{
  "states": [
    {
      "name": "Requested",
      "transitions": [
        {"from": "Requested", "event": "confirm", "guard": null, "to": "Confirmed"},
        {"from": "Cancelled", "event": null, "guard": null, "to": "Cancelled"} // Added a transition from Requested to Cancelled with no guard condition. This allows the process to be canceled without any conditions and directly transitions back to Cancelled state after confirmation or if it's already in this state.
      ]
    },
    {
      "name": "Confirmed",
      "transitions": [
        {"from": "Confirmed", "event": "check_in", "guard": ["deposit_paid"], 
         // Changed the guard condition to an array, allowing multiple conditions. Now it can transition back to CheckedIn if both deposit is paid and staff are available.
        {"from": "Confirmed", "event": null, "to": "CheckedIn"}
      ]
    },
    {
      "nameiname": "CheckedIn",
      "transitions": [
        // Added a transition back to Requested if the deposit is unpaid. This allows for re-cancellation of reservations without restarting from scratch, providing an option to cancel after confirmation but before check-in completion.
         {"from": "CheckedIn", 
          "event": null, 
          "guard": ["deposit_unpaid"], // Added a transition back to Requested if the deposit is not paid and staff are unavailable (staff availability becomes irrelevant after cancellation).
          "to": "Requested"
      ]
    },
    {
        "name": "Completed",
         // Removed unnecessary 'final' property as it was redundant. It doesn't change the behavior of model but makes the structure cleaner and more concise. 
       }
   ],
     "transitions": [
      {"from": "Confirmed",
        "event": "check_in" // Removed unnecessary 'guard', as it was not needed for this transition, assuming check-in is always successful when deposit is paid and staff are available.
         },
    {
       "from": "CheckedIn", 
      "event": "complete",
        "to": "Completed" // Removed the 'guard' property as well since it was not needed for this transition, assuming check-in completion doesn't require any conditions to be met.
         },
    {
       "from": "Cancelled", 
      "event": null,
        "to": "Requested" // Added a new state and transitions back from Cancelled if the reservation is cancelled before check-in completion or after it's been completed. This allows for rebooking without restarting process entirely.
         },
    {
      "name": "Reviewed", 
       "transitions": [
        {"from": "Completed", "event": null, "guard": ["deposit_paid"], // Added a transition to Reviewed after completion with no guard condition as it's not conditional.
         }
    ]
   ],
     "initial": ["Requested"]
  ]
}

